void require(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
float number(jass::Value value){return std::bit_cast<float>(value.bits);}
std::unique_ptr<ScriptSession> start(const wchar_t* root,const char* path,bool expansion=false,bool damageProbe=false){
    Archives archives(root);auto bytes=archives.readCandidates({path},ArchiveScope::Common);if(!bytes)throw std::runtime_error(std::string("Campaign map missing: ")+path);archives.mountMap(std::make_shared<const Bytes>(bytes->bytes),path);auto world=World::read(archives);auto info=world->data().info;MapStrings strings;if(auto wts=archives.readCandidates({"war3map.wts"},ArchiveScope::Map))strings=mapStrings(wts->bytes);auto program=jass::Program::read(archives);if(damageProbe){auto sources=program.sources();sources.push_back({"tower-probe.j",R"jass(
globals
    unit probeTower = null
    real probeDamage = 0.
endglobals
function ProbeDamage takes nothing returns nothing
    if GetEventDamageSource() == probeTower then
        set probeDamage = probeDamage + GetEventDamage()
    endif
endfunction
function ProbeTarget takes unit tower, unit target returns nothing
    local trigger t = CreateTrigger()
    set probeTower = tower
    call TriggerRegisterUnitEvent(t, target, EVENT_UNIT_DAMAGED)
    call TriggerAddAction(t, function ProbeDamage)
endfunction
)jass","tower damage probe"});program=jass::Program::parse(std::move(sources));}auto session=std::make_unique<ScriptSession>(jass::Module::compile(std::move(program)),info,std::move(strings));session->campaignContext(expansion,1);session->attachWorld(std::move(world));session->audioSimulationClock();session->audioMuted(true);session->configure();PlayerSetup setup(info,session->config());session->applySetup(setup);session->startMain();return session;
}
void advanceToGameplay(ScriptSession& session){for(int i=0;i<1320;++i)session.advance(.25);require(session.exitRequest()==SessionExit::None && session.userControl(),"Human06 did not reach gameplay");}
void continueDialog(ScriptSession& session){for(auto& [id,dialog]:session.dialogs())if(dialog->owners){require(!dialog->buttons.empty() && session.clickDialog(session.localPlayer().value_or(0),dialog->buttons.front()),"Outcome dialog could not continue");break;}}
