void secretPathing(const wchar_t* root){
    auto session=start(root,"Maps\\FrozenThrone\\Campaign\\HumanX03Secret.w3x",true);for(int i=0;i<500;++i)session->advance(.25);auto& vm=session->runtime();auto real=[&](float n){return vm.real(jass::Real::fromBits(std::bit_cast<unsigned>(n)));};auto unit=vm.invoke("CreateUnit",std::array{vm.handle("player",0x100006),vm.integer(int(ObjectData::code("nfrp"))),real(-288),real(7136),real(270)});require(session->units().contains(unit.bits),"Secret chapter attacker missing");auto state=session->units().at(unit.bits);vm.invoke("GroupAddUnit",std::array{vm.global("udg_AttackingUnits"),unit});require(vm.invoke("IssuePointOrderLoc",std::array{unit,vm.string("move"),vm.global("udg_PointWaitingRedirect01Left")}).bits,"Secret chapter redirect order rejected");session->advance(10);require(!state->pathing && std::bit_cast<float>(state->y.bits())<6720,"Attacker did not reach the waiting redirect after pathing was disabled");auto leader=vm.invoke("CreateUnit",std::array{vm.handle("player",0x100006),vm.integer(int(ObjectData::code("Npbm"))),real(-672),real(8192),real(270)});require(session->units().contains(leader.bits),"Secret chapter leader missing");auto leaderState=session->units().at(leader.bits);vm.invoke("GroupAddUnit",std::array{vm.global("udg_AttackingUnits"),leader});require(vm.invoke("IssuePointOrderLoc",std::array{leader,vm.string("move"),vm.global("udg_PointWaitingRedirect01Right")}).bits,"Secret chapter leader order rejected");session->advance(20);require(!leaderState->pathing && std::bit_cast<float>(leaderState->y.bits())<6784,"Leader did not reach the waiting region");std::cout<<"PASS HumanX03Secret attackers reach waiting redirects\n";
}
void secretBuild(const wchar_t* root,const char* towerType,int cost,bool protectPortal=false){
    auto session=start(root,"Maps\\FrozenThrone\\Campaign\\HumanX03Secret.w3x",true,true);for(int i=0;i<480;++i)session->advance(.25);require(session->userControl(),"Secret chapter did not reach gameplay");auto owner=session->localPlayer().value_or(0),type=ObjectData::code(towerType);std::uint32_t worker=0;for(auto& [id,unit]:session->units())if(unit->owner==owner && unit->type==ObjectData::code("n007") && std::bit_cast<float>(unit->x.bits())>400){worker=id;break;}require(worker && session->product(type).gold==cost,"Secret chapter builder or tower cost missing");auto real=[](float value){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(value));};PlayerCommand command;command.player=owner;command.kind=PlayerCommandKind::BuildAt;command.units={worker};command.objectType=type;command.xBits=real(832).bits();command.yBits=real(2176).bits();auto& vm=session->runtime();if(protectPortal)vm.invoke("SetUnitInvulnerable",std::array{vm.handle("unit",worker),vm.boolean(true)});auto protect=[&]{if(!protectPortal)return;auto portal=vm.global("gg_unit_h000_0002");if(portal.bits && session->units().contains(portal.bits)){auto unit=session->units().at(portal.bits);unit->life=unit->maxLife;}};std::string reason;while(!session->buildSite(worker,type,{real(832),real(2176)},reason) && session->simulationTime()<1800 && session->exitRequest()==SessionExit::None){protect();auto before=session->simulationTime();session->advance(.25);require(session->simulationTime()>before,"Secret chapter paused before tower became available");if(!session->units().contains(worker) || std::bit_cast<float>(session->units().at(worker)->life.bits())<=0)for(auto& [id,unit]:session->units())if(unit->owner==owner && unit->type==ObjectData::code("n007") && std::bit_cast<float>(unit->life.bits())>0){worker=id;break;}reason.clear();}command.units={worker};if(!session->buildSite(worker,type,{real(832),real(2176)},reason))std::cout<<"SITE "<<reason<<" time="<<session->simulationTime()<<"\n";require(dispatchPlayerCommand(*session,command)==1,"Secret chapter tower order rejected");std::uint32_t tower=0;std::set<std::uint32_t> targets;bool paid=false,finished=false,fired=false,damaged=false;for(int i=0;i<3200 && !damaged && session->exitRequest()==SessionExit::None;++i){protect();auto before=session->config().players[owner].states.at(1);auto time=session->simulationTime();session->advance(1./32);require(session->simulationTime()>time,"Secret chapter paused before tower attack");for(auto& [id,unit]:session->units())if(unit->owner==owner && unit->type==type && std::abs(std::bit_cast<float>(unit->x.bits())-832)<1 && std::abs(std::bit_cast<float>(unit->y.bits())-2176)<1){if(!tower){tower=id;paid=unit->construction && unit->construction->gold==cost && before-session->config().players[owner].states.at(1)==cost;}if(tower==id && !unit->construction)finished=true;}if(finished)for(auto& [id,projectile]:session->projectiles())if(projectile.source==tower && projectile.target){fired=true;if(targets.insert(projectile.target).second)vm.invoke("ProbeTarget",std::array{vm.handle("unit",tower),vm.handle("unit",projectile.target)});}damaged=number(vm.global("probeDamage"))>0;}require(tower && paid && finished && fired && damaged,"Secret chapter tower did not charge, complete, fire and deal damage");std::cout<<"PASS HumanX03Secret tower construction and attack time="<<session->simulationTime()<<" type="<<towerType<<"\n";
}
