    auto session=start(root,"Maps\\Campaign\\Human06.w3m");auto& vm=session->runtime();bool reachedGameplay=false,dialogShown=false,hadStructures=false;float conversions=0;auto structures=[&]{return vm.invoke("GetPlayerStructureCount",std::array{vm.handle("player",0x100001),vm.boolean(true)}).bits;};for(int i=0;i<16000 && session->exitRequest()==SessionExit::None;++i){session->advance(.25);if(session->simulationTime()>330 && session->userControl()){reachedGameplay=true;hadStructures=hadStructures || structures()>0;}conversions=std::max(conversions,number(vm.global("udg_MalganisConversions")));for(auto& [id,dialog]:session->dialogs())if(dialog->owners){require(hadStructures && structures()==0 && conversions<100 && vm.global("udg_GameOver").bits && session->results()[1] && *session->results()[1]==1,"Human06 displayed a dialog before defeat");dialogShown=true;require(!dialog->buttons.empty() && session->clickDialog(session->localPlayer().value_or(0),dialog->buttons.front()),"Human06 defeat dialog could not restart");break;}}
